class Solution {
  public int minRemovals(int[] nums, int target) {
    int size = 1 << 14;
    int[] dp = new int[size];
    java.util.Arrays.fill(dp, -1);
    dp[0] = 0;
    for (int x : nums) {
      int[] nd = dp.clone();
      for (int v = 0; v < size; v++) {
        if (dp[v] >= 0) nd[v ^ x] = Math.max(nd[v ^ x], dp[v] + 1);
      }
      dp = nd;
    }
    return target < size && dp[target] >= 0 ? nums.length - dp[target] : -1;
  }
}
